  const isSenior = age !== null && age >= 50;
  const relevant = (isSenior) || lower.includes('50 лет') || lower.includes('60 лет') || lower.includes('после 50') ||
    lower.includes('пожилой') || lower.includes('возраст') && lower.includes('тренировк');
  if (!relevant) return '';
