  lines.push('🧓 СИЛОВЫЕ ТРЕНИРОВКИ ПОСЛЕ 50 ЛЕТ:');
  if (age) lines.push(`(Твой возраст: ~${age} лет)`);
  lines.push('');
  lines.push('⚠️ ФИЗИОЛОГИЧЕСКИЕ ОСОБЕННОСТИ:');
