// ─── Conversation Starters: personalized quick-action suggestions ────────────

router.get('/starters', authenticate, async (req: AuthRequest, res: Response) => {
  try {
    const userId = req.userId!;
    const starters: Array<{ emoji: string; text: string; action?: string }> = [];

    const [user, lastWorkout, todayMeals, bodyWeight, activeProgram] = await Promise.all([
      prisma.user.findUnique({ where: { id: userId } }),
      prisma.workout.findFirst({
        where: { userId, completedAt: { not: null } },
        orderBy: { completedAt: 'desc' },
      }),
      prisma.meal.findMany({
        where: {
          userId,
          createdAt: {
            gte: new Date(new Date().setHours(0, 0, 0, 0)),
            lte: new Date(new Date().setHours(23, 59, 59, 999)),
          },
        },
      }),
      prisma.bodyWeight.findFirst({ where: { userId }, orderBy: { date: 'desc' } }),
      prisma.program.findFirst({ where: { userId, isActive: true } }),
    ]);

    const hour = new Date().getHours();
    const DAY_NAMES_SHORT = ['вс', 'пн', 'вт', 'ср', 'чт', 'пт', 'сб'];
    const dayShort = DAY_NAMES_SHORT[new Date().getDay()];

    // 1. Time-based meal suggestion
    if (todayMeals.length === 0 && hour >= 7 && hour < 11) {
      starters.push({ emoji: '🍳', text: 'Что мне поесть на завтрак?' });
    } else if (todayMeals.length <= 1 && hour >= 12 && hour < 15) {
      starters.push({ emoji: '🥗', text: 'Что приготовить на обед?' });
    } else if (hour >= 18 && hour < 22) {
      starters.push({ emoji: '🍽️', text: 'Что поесть на ужин?' });
    }

    // 2. Inactivity prompt
    if (lastWorkout) {
      const daysSince = Math.floor((Date.now() - new Date(lastWorkout.completedAt!).getTime()) / (1000 * 60 * 60 * 24));
      if (daysSince >= 3 && daysSince < 7) {
        starters.push({ emoji: '💪', text: `Давно не тренировался (${daysSince} дн). Что делать сегодня?` });
      } else if (daysSince >= 7) {
        starters.push({ emoji: '🔄', text: 'Хочу вернуться к тренировкам' });
      }
    }

    // 3. No program
    if (!activeProgram) {
      starters.push({ emoji: '📋', text: 'Составь мне программу тренировок' });
    }

    // 4. Weight logging (if last weight was >3 days ago)
    if (bodyWeight) {
      const daysSinceWeigh = Math.floor((Date.now() - new Date(bodyWeight.date).getTime()) / (1000 * 60 * 60 * 24));
      if (daysSinceWeigh >= 3) {
        starters.push({ emoji: '⚖️', text: 'Записать вес' });
      }
    } else {
      starters.push({ emoji: '⚖️', text: 'Записать вес' });
    }

    // 5. Profile gaps → natural questions
    const gaps = getProfileGaps(user);
    if (gaps.length > 0) {
      const top = gaps[0];
      starters.push({ emoji: '⚙️', text: `Рассчитай мои нормы КБЖУ` });
    }

    // 6. General starters (always available, lower priority)
    const generalStarters = [
      { emoji: '🧠', text: 'Как улучшить технику приседа?' },
      { emoji: '📈', text: 'Покажи мой прогресс' },
      { emoji: '💊', text: 'Какие добавки мне нужны?' },
      { emoji: '😴', text: 'Как улучшить восстановление?' },
    ];

    // Fill up to 6 starters total
    while (starters.length < 6 && generalStarters.length > 0) {
      starters.push(generalStarters.shift()!);
    }

    res.json({ starters: starters.slice(0, 6) });
  } catch (e) {
    console.error('Starters error:', e);
    res.json({ starters: [
      { emoji: '💪', text: 'Составь тренировку на сегодня' },
      { emoji: '🍽️', text: 'Что мне поесть?' },
      { emoji: '📈', text: 'Покажи мой прогресс' },
    ]});
  }
});

// Analyze food photo
router.post('/analyze-food', authenticate, async (req: AuthRequest, res: Response) => {
  try {
    const { imageBase64 } = req.body;
    if (!imageBase64) return res.status(400).json({ error: 'Изображение обязательно' });

    const user = await prisma.user.findUnique({ where: { id: req.userId } });

    const userInfo = user
      ? `Пользователь: ${user.gender === 'MALE' ? 'мужчина' : user.gender === 'FEMALE' ? 'женщина' : ''}, ${user.weightKg ? `вес ${user.weightKg} кг` : ''}, цель: ${user.goal || 'не указана'}.`
      : '';

    const prompt = `Ты — эксперт-нутрициолог. Проанализируй фото еды максимально точно.

${userInfo}

Для КАЖДОГО продукта на фото определи:
1. Название продукта (на русском)
2. Примерный вес в граммах (оценивай по размеру тарелки/порции)
3. Калорийность (ккал)
4. Белки (г)
5. Жиры (г)
6. Углеводы (г)

Используй стандартные значения КБЖУ из российских таблиц калорийности.
Будь точным в оценке размера порции — это критически важно.

Ответь СТРОГО в формате JSON:
{
  "items": [
    {
      "name": "название продукта",
      "weightGrams": 150,
      "calories": 200,
      "protein": 30,
      "fats": 5,
      "carbs": 10
    }
  ]
}

Только JSON, без комментариев и пояснений.`;

    // Retry loop: до 2 попыток
    const MAX_FOOD_RETRIES = 2;
    let lastError: string | null = null;

    for (let attempt = 0; attempt < MAX_FOOD_RETRIES; attempt++) {
      try {
        const text = await analyzeImage(imageBase64, prompt);
        const items = parseFoodResponse(text);

        if (!items || items.length === 0) {
          lastError = 'Не удалось распознать JSON из ответа AI';
          console.warn(`Food analysis attempt ${attempt + 1}: parse failed. Raw: ${text.slice(0, 200)}`);
          continue;
        }

        const validated = validateFoodItems(items);
        if (validated.length === 0) {
          lastError = 'Продукты не прошли валидацию';
          continue;
        }

        return res.json({ items: validated });
      } catch (analyzeError) {
        lastError = (analyzeError as Error).message;
        console.warn(`Food analysis attempt ${attempt + 1} failed:`, lastError);
        // Если ошибка сети/таймаут — подождём перед retry
        if (attempt < MAX_FOOD_RETRIES - 1) {
          await new Promise((r) => setTimeout(r, 1000));
        }
      }
    }

    // Если vision не сработал — fallback на text-only модель с описанием
    try {
      console.warn('Vision failed, attempting text-only fallback for food analysis');
      const fallbackText = await generate(
        `Пользователь сфотографировал еду. К сожалению, фото не удалось обработать. Попроси пользователя описать еду текстом (что ел, примерный размер порции), и ты рассчитаешь КБЖУ. Ответь на русском, кратко.`,
        { maxTokens: 256, temperature: 0.5 },
      );
      return res.status(422).json({
        error: 'Не удалось распознать еду на фото',
        suggestion: fallbackText || 'Попробуй описать еду текстом в чате с Iron Coach — он рассчитает КБЖУ.',
        retryable: true,
      });
    } catch {
      return res.status(500).json({
        error: lastError || 'Ошибка анализа фото',
        retryable: true,
      });
    }
  } catch (e) {
    console.error('Food analysis error:', e);
    res.status(500).json({ error: 'Ошибка анализа фото', retryable: true });
  }
});

